import { ListenerNode } from './listener-node';

export class ListenerNodePool {
    private poolReversedListTail?: ListenerNode;

    private toBePooledReversedListTail?: ListenerNode;

    public addNodeToPool(node: ListenerNode): void {
        node.listener = void 0;
        node.once = void 0;
        node.next = void 0;
        node.context = void 0;
        node.previous = this.poolReversedListTail;
        this.poolReversedListTail = node;
    }

    public getNodeFromPool(): ListenerNode {
        if (this.poolReversedListTail) {
            const node: ListenerNode = this.poolReversedListTail;
            this.poolReversedListTail = this.poolReversedListTail.previous;
            node.previous = void 0;
            return node;
        }
        return new ListenerNode();
    }

    public removeNodeFromFlow(node: ListenerNode): void {
        node.previous = this.toBePooledReversedListTail;
        this.toBePooledReversedListTail = node;
    }

    public returnNodesToPool(): void {
        let toBePooledNode: ListenerNode | undefined = this.toBePooledReversedListTail;
        while (toBePooledNode) {
            this.toBePooledReversedListTail = this.toBePooledReversedListTail!.previous;
            this.addNodeToPool(toBePooledNode);
            toBePooledNode = this.toBePooledReversedListTail;
        }
    }
}
